import{_ as s,o as t,c as i,ag as e}from"./chunks/framework.BLV0JUXI.js";const g=JSON.parse('{"title":"1.2 进阶应用：核心原理与多端编译机制","description":"逻辑层/视图层双线程模型、编译时与运行时差异，以及一份代码如何产出四端产物。","frontmatter":{"title":"1.2 进阶应用：核心原理与多端编译机制","description":"逻辑层/视图层双线程模型、编译时与运行时差异，以及一份代码如何产出四端产物。","tags":["核心原理","逻辑层","视图层","编译时"],"version":"3.2.0","difficulty":2},"headers":[],"relativePath":"guide/01-intro/advanced.md","filePath":"guide/01-intro/advanced.md","lastUpdated":1793196275000}'),n={name:"guide/01-intro/advanced.md"};function p(l,a,d,o,r,h){return t(),i("div",null,[...a[0]||(a[0]=[e(`<h1 id="_1-2-进阶应用-核心原理与多端编译机制" tabindex="-1">1.2 进阶应用：核心原理与多端编译机制 <a class="header-anchor" href="#_1-2-进阶应用-核心原理与多端编译机制" aria-label="Permalink to &quot;1.2 进阶应用：核心原理与多端编译机制&quot;">​</a></h1><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><ul><li>画出 uni-app 在小程序端的双线程模型，并解释数据从点击到渲染的完整路径</li><li>说清「编译时」和「运行时」各做了什么</li><li>理解为什么频繁修改数据会导致小程序卡顿（为模块 8 埋点）</li></ul><h2 id="双线程模型-小程序端最关键的架构" tabindex="-1">双线程模型（小程序端最关键的架构） <a class="header-anchor" href="#双线程模型-小程序端最关键的架构" aria-label="Permalink to &quot;双线程模型（小程序端最关键的架构）&quot;">​</a></h2><p>微信小程序从设计上把代码拆进两个线程：</p><ul><li><strong>逻辑层（AppService / JSCore）</strong>：运行你的 JS/TS：业务逻辑、Pinia store、网络请求、<code>uni.*</code> 调用。没有 DOM、没有 <code>window</code>。</li><li><strong>视图层（WebView / Skyline）</strong>：运行模板编译后的渲染代码，负责 UI 绘制与事件捕获。</li></ul><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sequenceDiagram</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  participant U as 用户</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  participant V as 视图层(WebView)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  participant B as native 桥(JSBridge)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  participant L as 逻辑层(JSCore)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  U-&gt;&gt;V: 点击按钮</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  V-&gt;&gt;B: 事件(tap, dataset)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  B-&gt;&gt;L: 序列化后转发</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  L-&gt;&gt;L: 执行 onClick / 修改 ref</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  L-&gt;&gt;B: 下发数据差异</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  B-&gt;&gt;V: setData 合并渲染</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  V-&gt;&gt;U: UI 更新</span></span></code></pre></div><p>每次响应式数据改变，最终都会变成一次（或被合并的）<strong>跨线程数据传输</strong>。数据要被序列化、经过原生桥、再在视图层 diff 渲染。这条链路就是后面所有性能经验的根源：</p><blockquote><p><strong>传输数据量越大、频率越高，UI 越卡。</strong></p></blockquote><p>H5 端逻辑层与视图层在同一个浏览器线程，不存在 JSBridge 成本；App 端则是「逻辑层独立 JSCore + 原生渲染/webview 渲染」的混合架构，成本介于两者之间。</p><h2 id="编译时-编译器替你做了什么" tabindex="-1">编译时：编译器替你做了什么 <a class="header-anchor" href="#编译时-编译器替你做了什么" aria-label="Permalink to &quot;编译时：编译器替你做了什么&quot;">​</a></h2><p>以 Vue 3 + Vite 版为例，源码进入构建后按目标平台走不同插件流水线：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.vue 单文件组件</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ├─ template 编译</span></span>
<span class="line"><span>   │    ├─ H5：编译为标准 Vue 虚拟节点（运行到浏览器 DOM）</span></span>
<span class="line"><span>   │    └─ 小程序：编译为各平台的 wxml/wxss/axml 等模板文件 + 渲染函数描述</span></span>
<span class="line"><span>   ├─ script</span></span>
<span class="line"><span>   │    ├─ &lt;script setup&gt; 经 Vue SFC 编译</span></span>
<span class="line"><span>   │    └─ 条件编译指令在这一步“剪枝”，不属于当前平台的代码直接消失</span></span>
<span class="line"><span>   ├─ style：rpx 换算、条件样式、css 变量</span></span>
<span class="line"><span>   └─ pages.json / manifest.json：转换为各平台配置</span></span></code></pre></div><p>值得记住的三点：</p><ol><li><strong>条件编译是物理删除，不是运行时 if</strong>。<code>// #ifdef MP-WEIXIN</code> 包裹的代码不会出现在 H5 产物里（在线体验：<a href="/uniapp-tutorial-pages/guide/07-adapt/advanced#在线演练">条件编译演练场</a>）。</li><li><strong>组件与 API 存在“映射表”</strong>：<code>&lt;view&gt;</code> 在 H5 产物里是一个带样式约定的 <code>&lt;uni-view&gt;</code> 自定义元素；<code>uni.request</code> 在 H5 走 XHR/fetch，在小程序走 <code>wx.request</code>。</li><li><strong>easycom 自动注册</strong>在编译期扫描 <code>components/组件名/组件名.vue</code>，免 import 即可使用（详见 <a href="/uniapp-tutorial-pages/guide/03-components/advanced">3.2</a>）。</li></ol><h2 id="运行时-一个点击事件的完整旅程" tabindex="-1">运行时：一个点击事件的完整旅程 <a class="header-anchor" href="#运行时-一个点击事件的完整旅程" aria-label="Permalink to &quot;运行时：一个点击事件的完整旅程&quot;">​</a></h2><p>以「点击按钮加入购物车」为例：</p><ol><li>视图层捕获 <code>tap</code>，把事件对象（含 dataset）经 JSBridge 发给逻辑层。</li><li>逻辑层执行 <code>cartStore.add(goodsId)</code>：Pinia 修改 state，Vue 的响应式系统标记依赖。</li><li>同一次事件循环内的多次数据修改会被 Vue 调度器<strong>合并</strong>，下一个微任务统一计算组件更新。</li><li>小程序运行时把更新序列化为 <code>setData</code> 数据（只传变化路径上的数据），经桥下发。</li><li>视图层合并数据、重新渲染对应节点；如果有原生反馈（震动/Toast），则并行调用原生能力。</li></ol><p>工程启示：</p><ul><li><strong>不要在一个滚动回调里高频改大对象</strong>：即便 Vue 合并了，最后一次 <code>setData</code> 仍可能携带巨大 payload。</li><li>长列表场景使用「分页数据 + 虚拟列表」，避免单个页面数据节点无限增长。</li><li>与视图无关的数据（计时器、缓存、接口原始报文）不必放进响应式 state，可用普通变量/模块单例存放。</li></ul><h2 id="h5、app、小程序运行时差异速查" tabindex="-1">H5、App、小程序运行时差异速查 <a class="header-anchor" href="#h5、app、小程序运行时差异速查" aria-label="Permalink to &quot;H5、App、小程序运行时差异速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>H5</th><th>微信小程序</th><th>App</th></tr></thead><tbody><tr><td>运行环境</td><td>浏览器</td><td>双线程 + JSBridge</td><td>独立 JSCore + 原生/webview 渲染</td></tr><tr><td>DOM/BOM</td><td>完整可用</td><td>不存在</td><td>受限（不建议依赖）</td></tr><tr><td>路由</td><td>可回退到浏览器 History</td><td>页面栈最多 10 层</td><td>同小程序模型</td></tr><tr><td>本地存储</td><td>localStorage</td><td>单 key 上限 1MB</td><td>类似小程序，另有 SQLite 方案</td></tr><tr><td>热更新</td><td>天然支持</td><td>需平台审核后发布</td><td>wgt 资源热更新（受政策约束）</td></tr><tr><td>调试</td><td>DevTools</td><td>微信开发者工具</td><td>HBuilderX 真机运行/调试</td></tr></tbody></table><h2 id="手动验证编译产物" tabindex="-1">手动验证编译产物 <a class="header-anchor" href="#手动验证编译产物" aria-label="Permalink to &quot;手动验证编译产物&quot;">​</a></h2><p>用 CLI 工程（下一章会搭建）可以直接看到剪枝效果：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># H5 产物：dist/build/h5，是标准静态站点</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:h5</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 微信小程序产物：dist/build/mp-weixin，用微信开发者工具导入即可</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:mp-weixin</span></span></code></pre></div><p>打开两个产物目录对比同一个页面：H5 目录里是 JS chunk + HTML；小程序目录里是 <code>app.js / app.json / pages/**/*.wxml</code>。对照源码搜索某个只写在 <code>#ifdef MP-WEIXIN</code> 里的字符串，你会发现它只存在于小程序产物中。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q：既然最终要 setData，为什么还需要 Vue 的响应式？</strong> Vue 负责精准算出“哪些组件依赖哪些数据”，让运行时可以只下发变化路径而不是整页数据。没有这层依赖追踪，每次更新都只能全量下发。</p><p><strong>Q：逻辑层和视图层为什么不放在一个线程？</strong> 小程序平台的安全与管控设计：逻辑层无法直接操作 UI，无法通过 JS 跳出沙箱；代价就是通信开销。Skyline 渲染引擎在持续降低这部分成本。</p><p><strong>Q：App 端是 webview 套壳吗？</strong> 不是简单套壳。uni-app App 端大量内置组件与导航是原生控件，页面逻辑跑在独立 JS 引擎；但复杂自定义 UI 区域仍可能基于 webview，性能分析时要区分（见 <a href="/uniapp-tutorial-pages/guide/08-perf/basics">8.1 性能度量</a>）。</p><p>下一篇 <a href="/uniapp-tutorial-pages/guide/01-intro/practice">1.3 实战案例</a> 会带你创建第一个项目，并实际跑通四端对比。</p>`,31)])])}const u=s(n,[["render",p]]);export{g as __pageData,u as default};
